with c as (select subscription_id, changed_at s, mrr_after m0 from raw_app_db.subscription_changes where change_type='new' and changed_at>='2024-01-01' and changed_at<'2025-01-01'),
l as (select c.subscription_id, c.m0, (select arg_max(mrr_after, changed_at) from raw_app_db.subscription_changes x where x.subscription_id=c.subscription_id and x.changed_at<=c.s+interval 12 month) m12 from c)
select count(*), sum(m0), sum(m12), sum(m12)/sum(m0), sum(case when m0=0 then 1 else 0 end), sum(case when m12=0 then 1 else 0 end) from l;

select 'spend' k, count(*) n, count(distinct spend_id) d, sum(spend_usd) s, min(spend_date) mn, max(spend_date) mx from raw_ads.ad_spend
union all select 'acc', count(*), count(distinct account_id), 0, min(signup_at), max(signup_at) from raw_app_db.accounts
union all select 'sub', count(*), count(distinct account_id), count(distinct subscription_id), min(started_at), max(started_at) from raw_app_db.subscriptions;
select channel, count(*), sum(spend_usd) from raw_ads.ad_spend where spend_date>='2025-01-01' and spend_date<'2026-01-01' group by 1;
select channel, count(*) from raw_app_db.accounts group by 1;
